#include "exgine/gles_probe_material.hpp"
namespace exgine {
bool bind_probe_material_set(OpenGLESApi&a,GlUInt program,const ReflectionProbeRegistry&r,const ProbeMaterialSet&s)noexcept{if(!program||!a.ActiveTexture||!a.BindTexture)return false;constexpr GlEnum CUBE=0x8513,T0=0x84C0;for(std::uint32_t i=0;i<s.count&&i<4;i++){auto*g=r.gpu_find(s.probes[i]->id);if(!g||!g->valid)return false;auto bind=[&](GlUInt tex,GlInt loc,GlEnum unit){if(loc>=0){a.ActiveTexture(unit);a.BindTexture(CUBE,tex);a.Uniform1i(loc,GlInt(unit-T0));}};bind(g->irradiance, a.GetUniformLocation(program,("u_probe_irradiance"+std::to_string(i)).c_str()), T0+2+i*2);bind(g->specular, a.GetUniformLocation(program,("u_probe_specular"+std::to_string(i)).c_str()), T0+3+i*2);auto posloc=a.GetUniformLocation(program,("u_probe_position_radius"+std::to_string(i)).c_str());auto wloc=a.GetUniformLocation(program,("u_probe_weight"+std::to_string(i)).c_str());if(posloc>=0)a.Uniform4f(posloc,s.probes[i]->position.x,s.probes[i]->position.y,s.probes[i]->position.z,s.probes[i]->blend_distance);if(wloc>=0)a.Uniform4f(wloc,s.weights[i],0,0,0);}auto countloc=a.GetUniformLocation(program,"u_probe_count");if(countloc>=0)a.Uniform1i(countloc,GlInt(s.count));return true;}
}